const params = new URLSearchParams(location.search);
const view = params.get('view') || 'entry';
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url = (v, id) => `?view=${v}${id ? `&id=${encodeURIComponent(id)}` : ''}`;
const appearance = document.querySelector('#appearance');
const system = matchMedia('(prefers-color-scheme: dark)');
function setAppearance() { document.documentElement.dataset.dyneTheme = appearance.value === 'system' ? (system.matches ? 'dark' : 'light') : appearance.value; }
appearance.value = params.get('appearance') || 'system';
appearance.addEventListener('change', setAppearance);
system.addEventListener('change', setAppearance);
setAppearance();
try {
  const response = await fetch('prototype-content.json');
  if (!response.ok) throw new Error('Content unavailable');
  const data = await response.json();
  const concept = id => data.concepts.find(c => c.id === id);
  // Only §52 is a complete context storyboard. Other refs retain their identity
  // and explicitly state the prototype's boundary instead of showing §52 as them.
  const sourceRefs = ids => `<p class="sources">Source paragraphs: ${ids.map(id => `<a href="${url('source', id)}">§${Number(id.slice(1))}</a>`).join(', ')}</p>`;
  const breadcrumb = current => `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${url('entry')}">Atlas</a><span aria-current="page">${esc(current)}</span></nav>`;
  const explanation = c => `<p class="kind">Paraphrase · the encyclical's account</p><p class="idea" id="idea">${esc(c.definition.text)}</p>${sourceRefs(c.definition.sourceRefs)}<h2 id="distinction">Necessary distinction</h2><p class="kind">Editorial interpretation</p><p>${esc(c.necessaryDistinction.text)}</p>${sourceRefs(c.necessaryDistinction.sourceRefs)}`;
  const edgeList = () => `<ol class="relationships">${data.relations.map(r => `<li><a href="${url('relation',r.id)}">${esc(concept(r.from).title)} ${esc(r.type)} ${esc(concept(r.to).title)}</a><p class="kind">Editorial interpretation</p><p>${esc(r.explanation.text)}</p>${sourceRefs(r.explanation.sourceRefs)}</li>`).join('')}</ol>`;
  const diagram = () => `<div class="neighborhood"><svg viewBox="0 0 560 300" aria-hidden="true" focusable="false"><a tabindex="-1" href="${url('concept','dignity')}"><rect x="125" y="10" width="310" height="55" rx="8"/><text x="280" y="44" text-anchor="middle">Human dignity</text></a>${data.relations.map((r,i)=>{const y=105+i*65;return `<path d="M100 ${y}H130"/><text x="20" y="${y+5}">${esc(r.type)}</text><a tabindex="-1" href="${url('relation',r.id)}"><rect x="140" y="${y-23}" width="390" height="48" rx="8"/><text x="335" y="${y+5}" text-anchor="middle">${esc(concept(r.to).title)}</text></a>`;}).join('')}</svg><p class="kind">Editorial relationships from Human dignity. Direction runs from dignity to each named destination; the full text list follows. Distance has no quantitative meaning.</p></div>`;
  const save = '<button class="dyne-button dyne-button--outline" id="save">Save demonstration place</button>';
  let body;
  if (view === 'entry') body = `${breadcrumb('Concept atlas')}<h1>Explore the ideas in Magnifica Humanitas</h1><p>Choose a concept and follow its connections.</p><p class="kind">Question groups are editorial entrances, not the source's own taxonomy.</p><div class="regions"><section class="region"><h2>What makes a person worthy?</h2><ul class="concept-links"><li><a href="${url('concept','dignity')}">Human dignity</a></li><li><a href="${url('concept','rights')}">Human rights</a></li></ul></section><section class="region"><h2>How do we live well together?</h2><ul class="concept-links"><li><a href="${url('concept','common-good')}">Common good</a></li><li><a href="${url('concept','ai-governance')}">Governing AI</a></li></ul></section></div><h2>Follow a named connection</h2>${diagram()}${edgeList()}<p>This four-concept sample demonstrates the atlas; the release exposes all 27 concepts.</p>`;
  else if (view === 'concept') { const c = concept(params.get('id') || 'dignity'); if (!c) throw new Error('Unknown concept'); body = `${breadcrumb(c.title)}<article><h1>${esc(c.title)}</h1>${explanation(c)}<h2>Follow the reasoning</h2><p class="kind">Editorial interpretation</p><p>${esc(data.relations.find(r=>r.from===c.id || r.to===c.id).explanation.text)}</p><h2>Connections</h2>${edgeList()}${c.id==='dignity'?`<p><a href="${url('foundations',c.id)}">Optional theological foundations</a></p>`:''}<div class="actions">${save}<a href="${url('entry')}">Return to atlas</a><a href="${url('trail')}">Open demonstration trail</a></div></article>`; }
  else if (view === 'relation') { const r=data.relations.find(r=>r.id===params.get('id')); if (!r) throw new Error('Unknown relationship'); body=`${breadcrumb('Relationship')}<h1>${esc(concept(r.from).title)} ${esc(r.type)} ${esc(concept(r.to).title)}</h1><p class="kind">Editorial interpretation</p><p>${esc(r.explanation.text)}</p>${sourceRefs(r.explanation.sourceRefs)}<div class="actions"><a href="${url('concept',r.from)}">Read ${esc(concept(r.from).title)}</a><a href="${url('concept',r.to)}">Read ${esc(concept(r.to).title)}</a></div>`; }
  else if (view === 'trail') { const step=params.get('id')==='rights'?2:1; const c=concept(step===1?'dignity':'rights'); body=`${breadcrumb('Demonstration trail')}<h1>Why is worth not a reward?</h1><p>Step ${step} of 2 · ${esc(c.title)}</p><p class="kind">Proposed demonstration sequence, not a published release trail.</p><article>${explanation(c)}<h2>Optional reflection</h2><p>Which meanings of dignity can change in the source's account?</p><button class="dyne-button" id="reveal" aria-expanded="false" aria-controls="feedback">Reveal explanation</button> <a href="#trail-actions">Skip reflection</a><section id="feedback" hidden><h3>Distinguish the meanings</h3><p class="kind">Editorial interpretation · §52</p><p>Moral conduct, social conditions and felt worth can change; ontological dignity is the source's unconditional claim. Understanding this distinction does not require agreement.</p>${sourceRefs(['p052'])}</section><div class="actions" id="trail-actions">${step===2?`<a href="${url('trail')}">Previous: Human dignity</a>`:''}<a href="${url(step===1?'trail':'end',step===1?'rights':undefined)}">${step===1?'Next: Human rights':'End trail'}</a><a href="${url(step===1?'trail':'end',step===1?'rights':undefined)}">Skip step</a><a href="${url('concept',c.id)}">Open full concept</a>${save}</div></article>`; }
  else if (view === 'end') body=`${breadcrumb('Trail ending')}<h1>You explored Human dignity and Human rights</h1><p>This demonstration ends here. Visits do not establish understanding or agreement.</p><div class="actions">${save}<a href="${url('entry')}">Return to atlas</a><a href="${url('trail')}">Revisit the question</a></div>`;
  else if (view === 'source') { const id=params.get('id')||'p052'; if(id!=='p052') body=`${breadcrumb('Source context')}<h1>Source context · §${esc(Number(id.slice(1)))}</h1><p>This paragraph is cited in the model; its context storyboard is not included in this bounded prototype. §52 is the worked context example.</p><a href="${url('source','p052')}">Inspect the §52 example</a>`; else body=`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${url('entry')}">Atlas</a><a href="${url('concept','dignity')}">Human dignity</a><span aria-current="page">Source §52</span></nav><article><h1>Source context · §52</h1><p>Leo XIV, <cite>Magnifica Humanitas</cite>, 15 May 2026 · English edition mh-en-owner-2026 · Original PDF page 12.</p><h2>Keep the distinction in view</h2><p class="kind">Editorial interpretation</p><p>“These aspects” refers to moral, social and existential dignity. The source distinguishes these from unconditional ontological dignity.</p><h2>Exact source quotation</h2><blockquote>${esc(data.quotation.text)}</blockquote><p class="sources">§52 · contiguous source span 457–512 · PDF page 12</p><h2>Notes and foundations</h2><p><a href="${url('note','n060')}">Source note 60</a> · <a href="${url('note','n061')}">Source note 61</a></p><p><a href="${url('foundations','dignity')}">Optional theological foundations</a></p><p>The full original includes devotional forms excluded from the adaptation. This context does not splice redacted text into an apparent quotation.</p><a href="https://www.vatican.va/content/leo-xiv/en/encyclicals/documents/20260515-magnifica-humanitas.html">Read the full original at the Holy See</a><div class="actions"><a href="${url('concept','dignity')}">Return to Human dignity</a></div></article>`; }
  else if(view==='foundations') body=`${breadcrumb('Optional foundations')}<h1>Optional theological foundations</h1><p class="kind">Editorial interpretation · §§50, 52–53</p><p>The source grounds intrinsic dignity in divine creation and love. This is an attributed theological premise; the secular entrance does not silently replace it with another proof.</p><a href="${url('concept','dignity')}">Return to Human dignity</a>`;
  else if(view==='note') body=`${breadcrumb('Source note')}<h1>Source note ${esc(params.get('id')?.slice(1))}</h1><p>Note reading is specified in the contract; this development storyboard demonstrates its named backlink only.</p><a href="${url('source','p052')}">Return to source §52</a>`;
  else if(view==='saved') body=`${breadcrumb('Saved places')}<h1>Your saved places</h1><p>Demonstration state · one place on this device. Production saving and migration are implemented later.</p><section id="saved-place"><h2>Human dignity</h2><p>Saved at the idea block.</p><div class="actions"><a href="${url('concept','dignity')}#idea">Resume Human dignity</a><button class="dyne-button dyne-button--outline" id="remove">Remove</button></div></section><section id="empty" hidden><h2>No saved places yet</h2><div class="actions"><button class="dyne-button" id="undo">Undo removal</button><a href="${url('entry')}">Explore the atlas</a></div></section>`;
  else throw new Error('Unknown storyboard');
  document.querySelector('main').innerHTML=body;
  document.title=`${document.querySelector('h1').textContent} · Magnifica Humanitas`;
  document.querySelector('#reveal')?.addEventListener('click',e=>{ const open=e.currentTarget.getAttribute('aria-expanded')==='true'; e.currentTarget.setAttribute('aria-expanded',String(!open)); document.querySelector('#feedback').hidden=open; });
  document.querySelector('#save')?.addEventListener('click',()=>{document.querySelector('#status').textContent='Demonstration place selected. This prototype does not persist it.';});
  function remove(hidden){document.querySelector('#saved-place').hidden=hidden;document.querySelector('#empty').hidden=!hidden;document.querySelector(hidden?'#undo':'#remove').focus();document.querySelector('#status').textContent=hidden?'Demonstration place removed. Undo is available.':'Demonstration place restored.';}
  document.querySelector('#remove')?.addEventListener('click',()=>remove(true));
  document.querySelector('#undo')?.addEventListener('click',()=>remove(false));
} catch {document.querySelector('main').innerHTML='<h1>Storyboard unavailable</h1><p>The requested content could not be loaded. <a href="?view=entry">Return to atlas</a>.</p>';}
